", "t": [["terminal", "{"command":"cd \"D:/Projects/local_ai/strata-lab/runs/work/hermes/jsondiff-1794053379\" && python - <<'EOF'\nfrom jsondiff import diff\ncases = [\n    (([1], [True]),          [\"~ $: [1] -> [true]\"]),          # == hides bool/int, must be ~, not []\n    (({\"a\": [1,2,3]}, {\"a\": [1,2]}), [\"- $.a[2]: 3\"]),\n    ((None, False),          [\"~ $: null -> false\"]),\n    (({}, {\"a\": {}}),        ['+ $.a: {}']),\n    (({\"a\": []}, {\"a\": [1]}),['+ $.a[0]: 1']),\n    (({\"b\": 1}, {\"a\": 2}),   [\"+ $.a: 2\", \"- $.b: 1\"]),\n    (([{\"x\": {\"y\": 1}}], [{\"x\": {\"y\": 1}}]), []),\n    (({\"a\": 1.0}, {\"a\": 1.0}), []),\n    (({\"n\": {\"deep\": [1, {\"k\": \"v\"}]}}, {\"n\": {\"deep\": [1, {\"k\": \"w\"}]}}), ['~ $.n.deep[1].k: \"v\" -> \"w\"']),\n    (([1, [2, [3]]], [1, [2, [4]]]), [\"~ $[1][1][0]: 3 -> 4\"]),\n    (({\"a\": {\"b\": 1}}, {\"a\": [1]}), ['~ $.a: {\"b\": 1} -> [1]']),   # dict->list is a whole-value ~\n    ((True, 1),              [\"~ $: true -> 1\"]),\n]\nfor a, b, want in cases:\n    got = diff(a, b)\n    assert got == want, (a, b, got, want)\n# sorted-ness spot check with many ops\nimport random\nops = diff({chr(97+i): i for i in range(26)}, {chr(98+i): i for i in range(26)})\nassert ops == sorted(ops)\nprint(\"all edge cases OK (%d ops in big case)\" % len(ops))\nEOF"}"]]}
